module pokemon_go_cost (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [31:0] N,\n    input wire [9:0] P_scaled, // P * 1000\n    output reg [63:0] cost,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] FINISH = 2'd2;\n    reg [1:0] state, next_state;\n\n    // Constants\n    localparam NUM_STATES = 101;\n    localparam FIXED_BITS = 32;\n    localparam [63:0] FIXED_ONE = 64'h1_0000_0000; // Q32.32 format\n    \n    // Internal registers\n    reg [63:0] prob [0:100];\n    reg [63:0] next_prob [0:100];\n    reg [63:0] C [0:100];\n    reg [63:0] T [0:100][0:100];\n    reg [63:0] total_cost;\n    reg [31:0] step_count;\n    reg [31:0] cycle_counter;\n    \n    // Intermediate computation\n    reg [63:0] q;\n    reg [63:0] P_real;\n    reg [63:0] q_power [0:100];\n    \n    // Loop counters\n    integer i, j, k;\n    \n    // Initialization and computation control\n    reg compute_ready;\n    \n    // Fixed-point multiplier\n    function [63:0] fp_mult;\n        input [63:0] a;\n        input [63:0] b;\n        reg [127:0] temp;\n        begin\n            temp = a * b;\n            fp_mult = temp[95:32]; // Mid 64 bits\n        end\n    endfunction\n    \n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            cost <= 64'd0;\n            done <= 1'b0;\n            total_cost <= 64'd0;\n            step_count <= 32'd0;\n            cycle_counter <= 32'd0;\n            compute_ready <= 1'b0;\n            \n            // Initialize arrays\n            for (i = 0; i < NUM_STATES; i = i+1) begin\n                prob[i] <= 64'd0;\n                C[i] <= 64'd0;\n                q_power[i] <= 64'd0;\n                for (j = 0; j < NUM_STATES; j = j+1) begin\n                    T[i][j] <= 64'd0;\n                end\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_counter <= 32'd0;\n                    if (start) begin\n                        // Precompute q, P_real, etc.\n                        P_real <= {32'd0, P_scaled, 22'd0}; // P_scaled / 1000 (Q32.32)\n                        q <= FIXED_ONE - P_real;\n                        \n                        // Precompute q_power\n                        q_power[0] <= FIXED_ONE;\n                        for (i = 1; i < NUM_STATES; i = i+1) begin\n                            q_power[i] <= fp_mult(q_power[i-1], q);\n                        end\n                        \n                        compute_ready <= 1'b1;\n                        state <= COMPUTE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (compute_ready) begin\n                        // Initialize prob to [0,0,...,1] at state 100\n                        for (i = 0; i < NUM_STATES; i = i+1) begin\n                            prob[i] <= (i == 100) ? FIXED_ONE : 64'd0;\n                        end\n                        step_count <= 32'd0;\n                        total_cost <= 64'd0;\n                        compute_ready <= 1'b0;\n                    end else if (step_count < N) begin\n                        // Compute immediate cost\n                        reg [63:0] cost_step;\n                        cost_step = 64'd0;\n                        for (i = 0; i < NUM_STATES; i = i+1) begin\n                            C[i] = (i == 0) ? {32'd5, 32'd0} : fp_mult({32'd5, 32'd0}, q_power[i]);\n                            cost_step = cost_step + fp_mult(prob[i], C[i]);\n                        end\n                        total_cost <= total_cost + cost_step;\n                        \n                        // Compute next_prob\n                        for (j = 0; j < NUM_STATES; j = j+1) begin\n                            next_prob[j] = 64'd0;\n                            for (i = 0; i < NUM_STATES; i = i+1) begin\n                                // Precompute T matrix\n                                T[i][j] = 64'd0;\n                                if (i == 0) begin\n                                    T[i][j] = (j == 100) ? FIXED_ONE : 64'd0;\n                                end else if (j == 0) begin\n                                    T[i][j] = fp_mult(P_real, q_power[i-1]);\n                                end else if (j == 100) begin\n                                    T[i][j] = q_power[i];\n                                end else if (i > j) begin\n                                    T[i][j] = fp_mult(P_real, q_power[i-j-1]);\n                                end\n                                next_prob[j] = next_prob[j] + fp_mult(prob[i], T[i][j]);\n                            end\n                        end\n                        \n                        // Update prob\n                        for (i = 0; i < NUM_STATES; i = i+1) begin\n                            prob[i] <= next_prob[i];\n                        end\n                        \n                        step_count <= step_count + 32'd1;\n                        cycle_counter <= cycle_counter + 32'd1;\n                    end else begin\n                        state <= FINISH;\n                        cost <= total_cost;\n                    end\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule